1: #!/usr/bin/env node
2: /**
3:  * book-intake — first-party MCP stdio server + localhost HTTP upload endpoint.
4:  *
5:  * 解决两个目录缺口:
6:  *   1) 浏览器→工作区文件通道:模板上传契约把整本书 base64 塞进 prompt,要求
7:  *      LLM 逐字节重发长 base64 到工具参数(实测 2KB 即开始出错)。本零件在
8:  *      本地起一个 HTTP 上传口,浏览器把文件直接 POST 落盘到工作区 uploads/,
9:  *      agent 只拿到路径,全程不碰 base64。
10:  *   2) EPUB 路径式解析:zip 工具只吃 base64 参数,epub 没有路径直读解析器。
11:  *
12:  * Safety: 上传落盘与读取都锚定 PART_WORKDIR,路径穿越一律拒绝;HTTP 服务只
13:  * 绑 127.0.0.1 随机端口,仅供本机浏览器使用,带 CORS(供内联预览页直传)。
14:  */
15: import { McpServer } from '@modelcontextprotocol/sdk/server/mcp.js';
16: import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
17: import { z } from 'zod';
18: import { createServer } from 'node:http';
19: import { readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
20: import { resolve, dirname, sep, basename } from 'node:path';
21: import AdmZip from 'adm-zip';
22: import * as cheerio from 'cheerio';
23: import iconv from 'iconv-lite';
24: 
25: const PART_WORKDIR = process.env.PART_WORKDIR || process.cwd();
26: const UPLOADS_DIR = resolve(PART_WORKDIR, 'uploads');
27: 
28: function insideRoot(root, target) {
29:   return target === root || target.startsWith(root + sep);
30: }
31: 
32: /* ── HTTP 上传口(随机端口,避免多 preset 并发撞口) ────────────────────── */
33: const uploads = [];
34: const httpServer = createServer((req, res) => {
35:   const send = (code, obj) => {
36:     res.writeHead(code, {
37:       'Content-Type': 'application/json; charset=utf-8',
38:       'Access-Control-Allow-Origin': '*',
39:       'Access-Control-Allow-Methods': 'POST, OPTIONS',
40:       'Access-Control-Allow-Headers': 'Content-Type, X-Filename',
41:     });
42:     res.end(JSON.stringify(obj));
43:   };
44:   if (req.method === 'OPTIONS') return send(204, { ok: true });
45:   if (req.method !== 'POST') return send(405, { ok: false, error: 'only POST' });
46:   if (req.url.split('?')[0] !== '/upload') return send(404, { ok: false, error: 'not found' });
47:   const q = new URLSearchParams(req.url.split('?')[1] || '');
48:   const rawName = decodeURIComponent(q.get('filename') || req.headers['x-filename'] || 'book.bin');
49:   const safeName = basename(rawName).replace(/[\\/:*?"<>|\x00-\x1f]/g, '_').slice(0, 120) || 'book.bin';
50:   const chunks = [];
51:   let size = 0;
52:   req.on('data', (c) => { size += c.length; if (size > 256 * 1024 * 1024) { req.destroy(); send(413, { ok: false, error: 'too large (>256MB)' }); } chunks.push(c); });
53:   req.on('end', () => {
54:     try {
55:       mkdirSync(UPLOADS_DIR, { recursive: true });
56:       const target = resolve(UPLOADS_DIR, safeName);
57:       if (!insideRoot(PART_WORKDIR, target)) return send(400, { ok: false, error: 'bad filename' });
58:       writeFileSync(target, Buffer.concat(chunks));
59:       uploads.push({ name: safeName, path: target, bytes: size, at: new Date().toISOString() });
60:       send(200, { ok: true, path: target, name: safeName, bytes: size });
61:     } catch (e) {
62:       send(500, { ok: false, error: String(e && e.message || e) });
63:     }
64:   });
65: });
66: httpServer.listen(0, '127.0.0.1');
67: httpServer.unref(); // 质检门契约:stdio 关闭进程必须退场,常驻监听不得钉住进程
68: const httpPort = await new Promise((r) => httpServer.once('listening', () => r(httpServer.address().port)));
69: 
70: /* ── MCP 工具 ─────────────────────────────────────────────────────────── */
71: const server = new McpServer({ name: 'book-intake', version: '0.0.1' });
72: 
73: server.registerTool('upload-info', {
74:   description:
75:     '返回本会话的文件接收服务信息:浏览器可把书籍文件 POST 到 url(参数 filename 或 X-Filename 头给文件名,'
76:     + 'body 为文件原始字节),文件会落盘到工作区 uploads/ 目录,返回其路径。'
77:     + 'agent 拿到路径后即可用 extract-epub / extract-text-file / 其他路径式解析工具处理,全程无需传输 base64。',
78:   inputSchema: {},
79: }, async () => ({
80:   content: [{ type: 'text', text: JSON.stringify({
81:     url: `http://127.0.0.1:${httpPort}/upload?filename=`,
82:     method: 'POST',
83:     body: '文件原始字节(直接 fetch body,不要包成 JSON)',
84:     note: '已上传 {count} 个文件,见 uploads 目录',
85:     uploads,
86:   }) }],
87: }));
88: 
89: server.registerTool('extract-epub', {
90:   description:
91:     '解析工作区内(或 uploads/ 下)的 EPUB 电子书文件:读 container.xml → content.opf 的 spine 顺序,'
92:     + '逐个提取 xhtml 章节为纯文本(标题取 h1/h2/h3,正文保留段落)。返回 {title, language, chapters:[{index,title,content}]}。'
93:     + '无 container.xml 的松散 zip 按条目名顺序取所有 xhtml/html 文件。',
94:   inputSchema: {
95:     path: z.string().describe('相对工作区的 epub 路径,如 uploads/xxx.epub'),
96:   },
97: }, async ({ path }) => {
98:   try {
99:     const target = resolve(PART_WORKDIR, path);
100:     if (!insideRoot(PART_WORKDIR, target)) return { isError: true, content: [{ type: 'text', text: `extract-epub: path escapes the workspace: ${path}` }] };
101:     if (!existsSync(target)) return { isError: true, content: [{ type: 'text', text: `extract-epub: file not found: ${path}` }] };
102:     const zip = new AdmZip(target);
103:     const entries = zip.getEntries().filter((e) => !e.isDirectory);
104:     const byName = Object.fromEntries(entries.map((e) => [e.entryName, e]));
105:     const textOf = (name) => (byName[name] ? byName[name].getData().toString('utf8') : null);
106: 
107:     let opfPath = null;
108:     let title = '';
109:     let language = '';
110:     const container = textOf('META-INF/container.xml');
111:     if (container) {
112:       const $c = cheerio.load(container, { xmlMode: true });
113:       opfPath = $c('rootfile').attr('full-path') || null;
114:     }
115:     let spine = [];
116:     if (opfPath) {
117:       const opf = textOf(opfPath);
118:       if (opf) {
119:         const $o = cheerio.load(opf, { xmlMode: true });
120:         title = $o('dc\\:title').first().text().trim() || $o('title').first().text().trim();
121:         language = $o('dc\\:language').first().text().trim() || '';
122:         const manifest = {};
123:         $o('manifest > item').each((_, el) => {
124:           const $el = $o(el);
125:           manifest[$el.attr('id')] = $el.attr('href');
126:         });
127:         $o('spine > itemref').each((_, el) => {
128:           const ref = $o(el).attr('idref');
129:           const href = manifest[ref];
130:           if (href) spine.push(href);
131:         });
132:       }
133:     }
134:     if (spine.length === 0) {
135:       // 松散 zip:按名取所有 xhtml/html
136:       spine = entries.map((e) => e.entryName).filter((n) => /\.x?html?$/i.test(n)).sort();
137:     }
138:     const chapters = [];
139:     spine.forEach((href, i) => {
140:       const full = opfPath && !href.includes('/') ? (dirname(opfPath) + '/' + href).replace(/^\.\//, '') : href;
141:       const src = byName[full] ? byName[full].getData().toString('utf8')
142:         : byName[href] ? byName[href].getData().toString('utf8') : null;
143:       if (!src) return;
144:       const $ = cheerio.load(src, { xmlMode: true });
145:       const chapTitle = $('h1,h2,h3').first().text().trim() || `第 ${i + 1} 章`;
146:       const body = $('body').length ? $('body') : $.root();
147:       const paras = [];
148:       body.find('p,h1,h2,h3,h4,li,blockquote,div').each((_, el) => {
149:         const t = $(el).text().replace(/\s+/g, ' ').trim();
150:         if (t) paras.push(t);
151:       });
152:       if (paras.length === 0) paras.push(body.text().replace(/\s+/g, ' ').trim());
153:       chapters.push({ index: i, title: chapTitle, content: paras.join('\n\n') });
154:     });
155:     return { content: [{ type: 'text', text: JSON.stringify({ title, language, chapters }) }] };
156:   } catch (e) {
157:     return { isError: true, content: [{ type: 'text', text: `extract-epub: ${String(e && e.message || e)}` }] };
158:   }
159: });
160: 
161: server.registerTool('extract-text-file', {
162:   description:
163:     '读取工作区内文本文件(书籍正文 txt/md 等),按指定编码解码为 UTF-8 返回。'
164:     + 'encoding 常用值:utf-8 / gbk / big5 / shift_jis(中文旧书常见 gbk/big5)。',
165:   inputSchema: {
166:     path: z.string().describe('相对工作区的文本文件路径,如 uploads/xxx.txt'),
167:     encoding: z.string().default('utf-8').describe('源文件编码,默认 utf-8'),
168:   },
169: }, async ({ path, encoding }) => {
170:   try {
171:     const target = resolve(PART_WORKDIR, path);
172:     if (!insideRoot(PART_WORKDIR, target)) return { isError: true, content: [{ type: 'text', text: `extract-text-file: path escapes the workspace: ${path}` }] };
173:     if (!existsSync(target)) return { isError: true, content: [{ type: 'text', text: `extract-text-file: file not found: ${path}` }] };
174:     const buf = readFileSync(target);
175:     const text = iconv.encodingExists(encoding) ? iconv.decode(buf, encoding) : buf.toString('utf8');
176:     return { content: [{ type: 'text', text }] };
177:   } catch (e) {
178:     return { isError: true, content: [{ type: 'text', text: `extract-text-file: ${String(e && e.message || e)}` }] };
179:   }
180: });
181: 
182: const transport = new StdioServerTransport();
183: await server.connect(transport);

