d(400, { ok: false, error: 'bad filename' });"},{"number":58,"text":"      writeFileSync(target, Buffer.concat(chunks));"},{"number":59,"text":"      uploads.push({ name: safeName, path: target, bytes: size, at: new Date().toISOString() });"},{"number":60,"text":"      send(200, { ok: true, path: target, name: safeName, bytes: size });"},{"number":61,"text":"    } catch (e) {"},{"number":62,"text":"      send(500, { ok: false, error: String(e && e.message || e) });"},{"number":63,"text":"    }"},{"number":64,"text":"  });"},{"number":65,"text":"});"},{"number":66,"text":"httpServer.listen(0, '127.0.0.1');"},{"number":67,"text":"httpServer.unref(); // 质检门契约:stdio 关闭进程必须退场,常驻监听不得钉住进程"},{"number":68,"text":"const httpPort = await new Promise((r) => httpServer.once('listening', () => r(httpServer.address().port)));"},{"number":69,"text":""},{"number":70,"text":"/* ── MCP 工具 ─────────────────────────────────────────────────────────── */"},{"number":71,"text":"const server = new McpServer({ name: 'book-intake', version: '0.0.1' });"},{"number":72,"text":""},{"number":73,"text":"server.registerTool('upload-info', {"},{"number":74,"text":"  description:"},{"number":75,"text":"    '返回本会话的文件接收服务信息:浏览器可把书籍文件 POST 到 url(参数 filename 或 X-Filename 头给文件名,'"},{"number":76,"text":"    + 'body 为文件原始字节),文件会落盘到工作区 uploads/ 目录,返回其路径。'"},{"number":77,"text":"    + 'agent 拿到路径后即可用 extract-epub / extract-text-file / 其他路径式解析工具处理,全程无需传输 base64。',"},{"number":78,"text":"  inputSchema: {},"},{"number":79,"text":"}, async () => ({"},{"number":80,"text":"  content: [{ type: 'text', text: JSON.stringify({"},{"number":81,"text":"    url: `http://127.0.0.1:${httpPort}/upload?filename=`,"},{"number":82,"text":"    method: 'POST',"},{"number":83,"text":"    body: '文件原始字节(直接 fetch body,不要包成 JSON)',"},{"number":84,"text":"    note: '已上传 {count} 个文件,见 uploads 目录',"},{"number":85,"text":"    uploads,"},{"number":86,"text":"  }) }],"},{"number":87,"text":"}));"},{"number":88,"text":""},{"number":89,"text":"server.registerTool('extract-epub', {"},{"number":90,"text":"  description:"},{"number":91,"text":"    '解析工作区内(或 uploads/ 下)的 EPUB 电子书文件:读 container.xml → content.opf 的 spine 顺序,'"},{"number":92,"text":"    + '逐个提取 xhtml 章节为纯文本(标题取 h1/h2/h3,正文保留段落)。返回 {title, language, chapters:[{index,title,content}]}。'"},{"number":93,"text":"    + '无 container.xml 的松散 zip 按条目名顺序取所有 xhtml/html 文件。',"},{"number":94,"text":"  inputSchema: {"},{"number":95,"text":"    path: z.string().describe('相对工作区的 epub 路径,如 uploads/xxx.epub'),"},{"number":96,"text":"  },"},{"number":97,"text":"}, async ({ path }) => {"},{"number":98,"text":"  try {"},{"number":99,"text":"    const target = resolve(PART_WORKDIR, path);"},{"number":100,"text":"    if (!insideRoot(PART_WORKDIR, target)) return { isError: true, content: [{ type: 'text', text: `extract-epub: path escapes the workspace: ${path}` }] };"},{"number":101,"text":"    if (!existsSync(target)) return { isError: true, content: [{ type: 'text', text: `extract-epub: file not found: ${path}` }] };"},{"number":102,"text":"    const zip = new AdmZip(target);"},{"number":103,"text":"    const entries = zip.getEntries().filter((e) => !e.isDirectory);"},{"number":104,"text":"    const byName = Object.fromEntries(entries.map((e) => [e.entryName, e]));"},{"number":105,"text":"    const textOf = (name) => (byName[name] ? byName[name].getData().toString('utf8') : null);"},{"number":106,"text":""},{"number":107,"text":"    let opfPath = null;"},{"number":108,"text":"    let title = '';"},{"number":109,"text":"    let language = '';"},{"number":110,"text":"    const container = textOf('META-INF/container.xml');"},{"number":111,"text":"    if (container) {"},{"number":112,"text":"      const $c = cheerio.load(container, { xmlMode: true });"},{"number":113,"text":"      opfPath = $c('rootfile').attr('full-path') || null;"},{"number":114,"text":"    }"},{"number":115,"text":"    let spine = [];"},{"number":116,"text":"    if (opfPath) {"},{"number":117,"text":"      const opf = textOf(opfPath);"},{"number":118,"text":"      if (opf) {"},{"number":119,"text":"        const $o = cheerio.load(opf, { xmlMode: true });"},{"number":120,"text":"        title = $o('dc\\:title').first().text().trim() || $o('title').first().text().trim();"},{"number":121,"text":"        language = $o('dc\\:language').first().text().trim() || '';"},{"number":122,"text":"        const manifest = {};"},{"number":123,"text":"        $o('manifest > item').each((_, el) => {"},{"number":124,"text":"          const $el = $o(el);"},{"number":125,"text":"          manifest[$el.attr('id')] = $el.attr('href');"},{"number":126,"text":"        });"},{"number":127,"text":"        $o('spine > itemref').each((_, el) => {"},{"number":128,"text":"          const ref = $o(el).attr('idref');"},{"number":129,"text":"          const href = manifest[ref];"},{"number":130,"text":"          if (href) spine.push(href);"},{"number":131,"text":"        });"},{"number":132,"text":"      }"},{"number":133,"text":"    }"},{"number":134,"text":"    if (spine.length === 0) {"},{"number":135,"text":"      // 松散 zip:按名取所有 xhtml/html"},{"number":136,"text":"      spine = entries.map((e) => e.entryName).filter((n) => /\.x?html?$/i.test(n)).sort();"},{"number":137,"text":"    }"},{"number":138,"text":"    const chapters = [];"},{"number":139,"text":"    spine.forEach((href, i) => {"},{"number":140,"text":"      const full = opfPath && !href.includes('/') ? (dirname(opfPath) + '/' + href).replace(/^\.\//, '') : href;"},{"number":141,"text":"      const src = byName[full] ? byName[full].getData().toString('utf8')"},{"number":142,"text":"        : byName[href] ? byName[href].getData().toString('utf8') : null;"},{"number":143,"text":"      if (!src) return;"},{"number":144,"text":"      const $ = cheerio.load(src, { xmlMode: true });"},{"number":145,"text":"      const chapTitle = $('h1,h2,h3').first().text().trim() || `第 ${i + 1} 章`;"},{"number":146,"text":"      const body = $('body').length ? $('body') : $.root();"},{"number":147,"text":"      const paras = [];"},{"number":148,"text":"      body.find('p,h1,h2,h3,h4,li,blockquote,div').each((_, el) => {"},{"number":149,"text":"        const t = $(el).text().replace(/\s+/g, ' ').trim();"},{"number":150,"text":"        if (t) paras.push(t);"},{"number":151,"text":"      });"},{"number":152,"text":"      if (paras.length === 0) paras.push(body.text().replace(/\s+/g, ' ').…[截断]

